#' BTD
#'
#' 
#' @param case .
#' @param controls .
#' @param sd .
#' @param sample_size .
#' @param alternative .
#' @param credible_interval .
#' @param credible_level .
#' @param iter .
#' @param show_plot .
#' @param show_txt_output .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$resultsTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$textOutput} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$resultsTable$asDF}
#'
#' \code{as.data.frame(results$resultsTable)}
#'
#' @export
btd <- function(
    case = 0,
    controls = 0,
    sd = 0,
    sample_size = 0,
    alternative = "less",
    credible_interval = TRUE,
    credible_level = 95,
    iter = 1000,
    show_plot = FALSE,
    show_txt_output = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("btd requires jmvcore to be installed (restart may be required)")


    options <- btdOptions$new(
        case = case,
        controls = controls,
        sd = sd,
        sample_size = sample_size,
        alternative = alternative,
        credible_interval = credible_interval,
        credible_level = credible_level,
        iter = iter,
        show_plot = show_plot,
        show_txt_output = show_txt_output)

    analysis <- btdClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

